//! Embeds the DirectShow driver into the executable (ADR-0026). Windows COM cannot load
//! a filter from memory (`InprocServer32` needs a path), so the DLL travels inside the
//! exe and `camera::driver` writes it next to the executable on demand.
//!
//! A committed placeholder (or a missing DLL) produces `None`, so `cargo run` and
//! `tauri dev` keep using the CMake build through `driver::dev_driver_path()` (ADR-0017).

use std::env;
use std::fs;
use std::path::{Path, PathBuf};

#[path = "src/camera/driver_embed.rs"]
mod driver_embed;

const NO_DRIVER: &str = "\
// Generated by build.rs: this build carries no embedded driver.
pub static EMBEDDED_DRIVER: Option<&[u8]> = None;
pub const EMBEDDED_DRIVER_VERSION: Option<u32> = None;
";

fn main() {
    embed_driver();
    tauri_build::build();
}

fn embed_driver() {
    let manifest =
        PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("cargo sets CARGO_MANIFEST_DIR"));
    let driver = manifest.join("resources").join("MeetBurnerCamera.dll");
    let header = manifest.join("../../../native/vcam-windows/common/meetburner_camera.h");

    println!("cargo:rerun-if-changed={}", driver.display());
    println!("cargo:rerun-if-changed={}", header.display());

    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let generated = if target_os == "windows" {
        embedded_source(&driver, &header)
    } else {
        NO_DRIVER.to_string()
    };

    let out = PathBuf::from(env::var("OUT_DIR").expect("cargo sets OUT_DIR"));
    fs::write(out.join("embedded_driver.rs"), generated).expect("write embedded_driver.rs");
}

/// `Some(include_bytes!(...))` only when the resource is a real DLL; the placeholder and
/// builds without the native project keep the dev-tree path.
fn embedded_source(driver: &Path, header: &Path) -> String {
    let bytes = fs::read(driver).unwrap_or_default();
    if !driver_embed::is_real_dll(&bytes) {
        return NO_DRIVER.to_string();
    }
    let version = fs::read_to_string(header)
        .ok()
        .and_then(|text| driver_embed::parse_driver_version(&text));
    let version = match version {
        Some(version) => format!("Some({version}u32)"),
        None => "None".to_string(),
    };
    format!(
        "pub static EMBEDDED_DRIVER: Option<&[u8]> = Some(include_bytes!({:?}));\n\
         pub const EMBEDDED_DRIVER_VERSION: Option<u32> = {version};\n",
        driver.display().to_string()
    )
}
